//! `migrate --seed` plan import: every programme project's units as real board cards.
//!
//! The document is generated by `scripts/build-plan-seed.py` and committed as `seed/plans.json`
//! (the design pack's DESIGN fallback is the same document as `docs/design/data/plan-seed.js`).
//! The unit is the GitHub issue; a project with no issue gets one plan-level card.
//!
//! **Idempotent, precisely.** A board is the schema's `(tenant, project, name)` row; a lane is
//! found by `(board, kind)` before it is inserted; a card is found by `card.meta.unit_key`.
//! A second run with an unchanged document creates no row and bumps no version. The seed owns
//! the card name only while it still equals `meta.seed_name`, merges `card.meta`, and never
//! touches a card that is leased or has a live run. Reconciliation is one-way: a card in
//! `intake` may advance to `done` when its issue closes; a card a person moved stays there.

use std::collections::HashMap;

use chrono::{DateTime, Utc};
use conveyor_domain::{Code, ListKind, TenantId};
use rust_decimal::Decimal;
use serde::Deserialize;
use serde_json::{Value, json};
use sqlx::{PgConnection, PgPool};
use uuid::Uuid;

use crate::board::{BoardLanes, ensure_board_from_template_tx, template_lanes_tx};
use crate::position::APPEND_STEP;
use crate::scope::begin_scoped;
use crate::seed::SeedError;
use crate::seed_programme::targets;

/// The checked-in plan document.
pub const PLAN_EXPORT: &str = include_str!("../../../seed/plans.json");

/// The board every seeded project gets (the same name `projects.create` uses).
const BOARD_NAME: &str = "Board";
/// The catalogue template whose lane kinds every board is built from.
const TEMPLATE_CODE: &str = "standard";

/// The document's top level.
#[derive(Debug, Deserialize)]
pub struct PlanSeedExport {
    /// The document format; only `1` is accepted.
    pub version: u32,
    /// Every project in the programme.
    pub projects: Vec<PlanProjectSeed>,
}

/// One project's units.
#[derive(Debug, Deserialize)]
pub struct PlanProjectSeed {
    /// The project's natural key (`S00`…`T17`, or a cross-cutting key).
    pub project_key: String,
    /// The plan path.
    #[serde(default)]
    pub plan: String,
    /// `v1` or `v2`.
    #[serde(default)]
    pub track: String,
    /// The plan's own status prose.
    #[serde(default)]
    pub plan_status: String,
    /// Project-level dependencies (SPEC §12 for a T slice).
    #[serde(default)]
    pub depends_on: Vec<String>,
    /// The cards this project owns.
    pub units: Vec<PlanUnitSeed>,
}

/// One unit = one card.
#[derive(Debug, Deserialize)]
pub struct PlanUnitSeed {
    /// Stable unit id: `issue-<n>` or `plan-<KEY>`.
    pub unit_key: String,
    /// The card name.
    pub title: String,
    /// The GitHub issue, when the unit is one.
    #[serde(default)]
    pub issue: Option<i64>,
    /// `OPEN` or `CLOSED`.
    pub state: String,
    /// The card type code (a row in `card_type`).
    pub card_type: String,
    /// The process this unit starts (`<card_type>.READY`).
    pub process_key: String,
    /// The plan path this unit belongs to.
    #[serde(default)]
    pub plan: String,
    /// The slice's gate text, for a T unit.
    #[serde(default)]
    pub gate: Option<String>,
}

/// What one seed run did in one tenant.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct PlanCounts {
    /// Cards inserted.
    pub created: i64,
    /// Cards whose content or lane changed.
    pub updated: i64,
    /// Cards already at the seeded content.
    pub skipped: i64,
}

/// Parse the embedded document. A malformed document is a build-time error, never a data error.
pub fn plan_export() -> Result<PlanSeedExport, SeedError> {
    let export: PlanSeedExport = serde_json::from_str(PLAN_EXPORT)
        .map_err(|error| SeedError::PlanDocument(error.to_string()))?;
    if export.version != 1 {
        return Err(SeedError::PlanDocument(format!(
            "unsupported version {}",
            export.version
        )));
    }
    Ok(export)
}

/// Apply the plan document to one tenant, or to every active tenant.
pub async fn seed_plans(
    pool: &PgPool,
    tenant_slug: Option<&str>,
) -> Result<Vec<(String, PlanCounts)>, SeedError> {
    let export = plan_export()?;
    let targets = targets(pool, tenant_slug).await?;
    let mut results = Vec::with_capacity(targets.len());
    for (tenant_id, slug) in targets {
        let tenant = TenantId::from_uuid(tenant_id)?;
        let mut tx = begin_scoped(pool, tenant).await?;
        let mut counts = PlanCounts::default();
        for project in &export.projects {
            seed_project(&mut tx, tenant, project, &mut counts).await?;
        }
        tx.commit().await?;
        results.push((slug, counts));
    }
    Ok(results)
}

#[derive(Debug, sqlx::FromRow)]
struct CardRow {
    id: Uuid,
    list_id: Uuid,
    name: String,
    meta: Value,
    lease_token: Option<Uuid>,
    archived_at: Option<DateTime<Utc>>,
}

async fn seed_project(
    conn: &mut PgConnection,
    tenant: TenantId,
    seed: &PlanProjectSeed,
    counts: &mut PlanCounts,
) -> Result<(), SeedError> {
    let existing: Option<(Uuid, String)> =
        sqlx::query_as("SELECT id, status FROM project WHERE tenant_id = $1 AND key = $2")
            .bind(tenant.as_uuid())
            .bind(&seed.project_key)
            .fetch_optional(&mut *conn)
            .await?;
    let Some((project_id, _status)) = existing else {
        return Err(SeedError::PlanMissing("project", seed.project_key.clone()));
    };

    // The `it` matrix is the only seeded type that admits the plan card types; `program` has
    // an empty matrix and makes every card unmovable.
    sqlx::query(
        "UPDATE project
            SET project_type_code = 'it', version = version + 1, updated_at = now()
          WHERE tenant_id = $1 AND id = $2 AND project_type_code IS DISTINCT FROM 'it'",
    )
    .bind(tenant.as_uuid())
    .bind(project_id)
    .execute(&mut *conn)
    .await?;

    let code =
        Code::parse(TEMPLATE_CODE).map_err(|error| SeedError::PlanDocument(error.to_string()))?;
    let kinds = template_lanes_tx(&mut *conn, tenant, &code)
        .await?
        .ok_or_else(|| SeedError::PlanMissing("board_template", TEMPLATE_CODE.to_owned()))?;
    let BoardLanes { board, lists } = ensure_board_from_template_tx(
        &mut *conn,
        tenant,
        project_id,
        BOARD_NAME,
        &kinds,
        json!({}),
    )
    .await?;

    let kinds_by_list: HashMap<Uuid, ListKind> =
        lists.iter().map(|list| (list.id, list.kind)).collect();
    let target = |state: &str| {
        if state == "CLOSED" {
            ListKind::Done
        } else {
            ListKind::Intake
        }
    };

    let existing_cards: Vec<CardRow> = sqlx::query_as(
        "SELECT id, list_id, name, meta, lease_token, archived_at
           FROM card WHERE tenant_id = $1 AND board_id = $2",
    )
    .bind(tenant.as_uuid())
    .bind(board.id)
    .fetch_all(&mut *conn)
    .await?;
    let mut by_unit: HashMap<String, CardRow> = HashMap::new();
    for row in existing_cards {
        if let Some(unit_key) = row.meta.get("unit_key").and_then(Value::as_str) {
            by_unit.insert(unit_key.to_owned(), row);
        }
    }

    let mut position: Decimal = sqlx::query_scalar(
        "SELECT COALESCE(max(position), 0) FROM card WHERE tenant_id = $1 AND board_id = $2",
    )
    .bind(tenant.as_uuid())
    .bind(board.id)
    .fetch_one(&mut *conn)
    .await?;

    for unit in &seed.units {
        let wanted_kind = target(&unit.state);
        let Some(wanted_list) = lists.iter().find(|list| list.kind == wanted_kind) else {
            return Err(SeedError::PlanMissing(
                "list",
                wanted_kind.as_str().to_owned(),
            ));
        };
        let card_type_id: Option<Uuid> = sqlx::query_scalar(
            "SELECT id FROM card_type
              WHERE tenant_id = $1 AND code = $2 AND is_active",
        )
        .bind(tenant.as_uuid())
        .bind(&unit.card_type)
        .fetch_optional(&mut *conn)
        .await?;
        let Some(card_type_id) = card_type_id else {
            return Err(SeedError::PlanMissing("card_type", unit.card_type.clone()));
        };

        let unit_meta = json!({
            "unit_key": unit.unit_key,
            "issue": unit.issue,
            "plan": unit.plan,
            "process_key": unit.process_key,
            "seed_name": unit.title,
            "card_type": unit.card_type,
            "depends_on": &seed.depends_on,
            "gate": &unit.gate,
        });

        match by_unit.get(&unit.unit_key) {
            Some(card) => {
                if card.archived_at.is_some() {
                    counts.skipped += 1;
                    continue;
                }
                let live = card.lease_token.is_some() || live_run_tx(conn, tenant, card.id).await?;
                if live {
                    counts.skipped += 1;
                    continue;
                }
                let merged = merge_meta(&card.meta, &unit_meta);
                let seeded_name = card.meta.get("seed_name").and_then(Value::as_str);
                let rename = seeded_name == Some(card.name.as_str()) && card.name != unit.title;
                let current_kind = kinds_by_list.get(&card.list_id).copied();
                let advance =
                    current_kind == Some(ListKind::Intake) && wanted_kind == ListKind::Done;
                if !rename && !advance && merged == card.meta {
                    counts.skipped += 1;
                    continue;
                }
                let list_id = if advance {
                    wanted_list.id
                } else {
                    card.list_id
                };
                sqlx::query(
                    "UPDATE card
                        SET name = $3, meta = $4, list_id = $5,
                            prev_list_id = CASE WHEN $5 <> list_id THEN list_id ELSE prev_list_id END,
                            list_changed_at = CASE WHEN $5 <> list_id THEN now() ELSE list_changed_at END,
                            version = version + 1, updated_at = now()
                      WHERE tenant_id = $1 AND id = $2",
                )
                .bind(tenant.as_uuid())
                .bind(card.id)
                .bind(if rename { unit.title.as_str() } else { card.name.as_str() })
                .bind(&merged)
                .bind(list_id)
                .execute(&mut *conn)
                .await?;
                counts.updated += 1;
            }
            None => {
                position += Decimal::from(APPEND_STEP);
                sqlx::query(
                    "INSERT INTO card
                        (tenant_id, board_id, list_id, card_type_id, name, description, position, meta)
                     VALUES ($1, $2, $3, $4, $5, '', $6, $7)",
                )
                .bind(tenant.as_uuid())
                .bind(board.id)
                .bind(wanted_list.id)
                .bind(card_type_id)
                .bind(&unit.title)
                .bind(position)
                .bind(&unit_meta)
                .execute(&mut *conn)
                .await?;
                counts.created += 1;
            }
        }
    }
    Ok(())
}

async fn live_run_tx(
    conn: &mut PgConnection,
    tenant: TenantId,
    card_id: Uuid,
) -> Result<bool, SeedError> {
    let live: bool = sqlx::query_scalar(
        "SELECT EXISTS (
             SELECT 1 FROM run
              WHERE tenant_id = $1 AND card_id = $2
                AND status IN ('queued', 'running', 'waiting_approval'))",
    )
    .bind(tenant.as_uuid())
    .bind(card_id)
    .fetch_one(&mut *conn)
    .await?;
    Ok(live)
}

/// The seed owns its named keys; every other key in `existing` survives.
fn merge_meta(existing: &Value, seed: &Value) -> Value {
    let mut merged = existing.as_object().cloned().unwrap_or_default();
    if let Some(map) = seed.as_object() {
        for (key, value) in map {
            merged.insert(key.clone(), value.clone());
        }
    }
    Value::Object(merged)
}
